// TH16 v1.00a Stage 2 midboss-wave transcription.
// Source: st02.ecl.txt MainSub03:1013-1028 (entry), GirlD01:488-511,
//         GirlD01_at:513-554 (dependencies).  Ranks 0..3 come from the
//         source difficulty masks; task declares ranks [0,3].
//
// Source/card mapping:
//   MainSub03 wait(300) x3, enmCreate GirlD01 at (0,-24)/(140,-24)/(-140,-24)
//     -> pattern(): 120-frame shell buffer, then spawn_enemy at the same
//        three world points, 300 source frames apart.
//   GirlD01 setHurtbox(32,32) / setHitbox(24,24)
//     -> set_hurtbox(16fx) / set_hitbox(12fx)  (circle branch: first value * 0.5)
//   GirlD01 moveVel(pi/2, 3); moveVelTime(80, mode1, pi/2, 0)
//     -> move_vel(0, 90deg, 3fx, EASE_LINEAR); move_vel(80, 90deg, 0fx, EASE_QUAD_IN)
//        (source mode 1 = t^2, not linear)
//   GirlD01 moveSpeedTime(120, mode1, -0.6)
//     -> move_speed(120, -0.6fx, EASE_QUAD_IN)
//   GirlD01_at: wait(60); etNew; etAim(10); etSprite(8,4); count 3/6/8/12;
//   etAngle(0,0,0.05235988); etSpeed(diff value, 1.6); 30 volleys every 10
//   frames with alpha -= %F1; etEx ANIM(1) + ANGLE_ACCEL(120, r=0, s=%F0)
//     -> sh_ring(1) + sh_aim(0) + sh_count(ways,1) + sh_speed(speed,0)
//        + sh_angle(alpha,0) + sh_xform(SPIN(f0)).
//        etAim mode10 with one layer is a full ring: alpha + 2*pi*i/N.
//        ANIM(a=1) is the approved birth-animation omission; its -4*velocity
//        birth shift is kept via sh_dist(-4*speed) (transcription-policy).
//        ANGLE_ACCEL: 120 frames of omega = +-0.015708 rad/frame (= 0.9 deg).

const TH16_RICE: int = 480;          // etSprite(0, 8, 4)

const TIME_LIMIT: int = 2524;        // 120 buffer + 2400 source window + 4
const OPENING_BUFFER: int = 120;
const BULLET_COLOR: int = 4;
const VOLLEYS: int = 30;
const VOLLEY_GAP: int = 10;

// Source etEx ANGLE_ACCEL: a=120, r=0.0, s=+-0.015708 (0.9 deg per frame).
xformdef SPIN(omega: angle) {
    @120 set_ang_vel(omega);
    set_ang_vel(0deg);
}

async sub girl_shot(f0: angle, f1: angle) {
    var ways: int = 3;
    var speed: fx = 1.6fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { ways = 6; }
    if rank == RANK_HARD { ways = 8; speed = 2.5fx; }
    if rank == RANK_LUNATIC { ways = 12; speed = 2.9fx; }

    wait(60);
    sh_reset(0);
    sh_sprite(0, TH16_RICE, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, 0fx - 4fx * speed);
    sh_xform(0, SPIN(f0));

    var alpha: angle = 0deg;
    for i in 0..VOLLEYS {
        sh_angle(0, alpha, 0deg);
        alpha = alpha - f1;
        sh_fire(0);
        wait(VOLLEY_GAP);
    }
}

async sub girl_d01(f0: angle, f1: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_shot(f0, f1);
    wait(200);
    move_speed(120, 0fx - 0.6fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -24fx, 1700, 0, 0, 0, girl_d01(0.9deg, 14deg));
    wait(300);
    _ = spawn_enemy(140fx, -24fx, 1700, 0, 0, 0, girl_d01(-0.9deg, -14deg));
    wait(300);
    _ = spawn_enemy(-140fx, -24fx, 1700, 0, 0, 0, girl_d01(0.9deg, 14deg));
    wait(300);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
